--
-- The file pdf-lib.esm.min.js is stored below as hex. Do not edit.
-- Run it connected as the schema that owns the application objects.
set define off feedback off
create table esign_js_chunks (seq number primary key, piece raw(1000));
commit;
create table esign_js_file (src blob);
declare
    l_src blob;
begin
    dbms_lob.createtemporary(l_src, true);
    for c in (select piece from esign_js_chunks order by seq) loop
        dbms_lob.writeappend(l_src, utl_raw.length(c.piece), c.piece);
    end loop;
    commit;
end;
/
create or replace mle module pdf_lib language javascript version '1.17.1'
    using blob (select src from esign_js_file);
/
drop table esign_js_chunks purge;
drop table esign_js_file purge;
create or replace mle env esign_pdf_env imports ('pdf-lib' module pdf_lib);
set feedback on
